define(["editor_tiny/loader","editor_tiny/utils","tiny_zoomclassroom/common","tiny_zoomclassroom/options","tiny_zoomclassroom/commands","tiny_zoomclassroom/configuration","tiny_zoomclassroom/render"], function(Loader, Utils, Common, Options, Commands, Configuration, Render) {










return new Promise(async(resolve) => {
    const [tinyMCE, pluginMetadata, setupCommands] = await Promise.all([
        Loader.getTinyMCE(),
        Utils.getPluginMetadata(Common.component, Common.pluginName),
        Commands.getSetup(),
    ]);

    tinyMCE.PluginManager.add(Common.pluginName, (editor) => {
        Options.register(editor);
        setupCommands(editor);

        const hydrateEditor = () => {
            const body = editor.getBody();
            if (body) {
                Render.upgradePlaceholdersInRoot(body);
            }
        };

        const dehydrateHtml = (event) => {
            if (!event || typeof event.content !== 'string') {
                return;
            }

            const tempRoot = editor.getDoc().createElement('div');
            tempRoot.innerHTML = event.content;
            Render.downgradePlaceholdersInRoot(tempRoot);
            event.content = tempRoot.innerHTML;
        };

        editor.on('init', hydrateEditor);
        editor.on('SetContent', hydrateEditor);
        editor.on('ExecCommand', hydrateEditor);
        editor.on('Change', hydrateEditor);
        editor.on('SaveContent', dehydrateHtml);

        return pluginMetadata;
    });

    resolve([Common.pluginName, Configuration]);
});

});
